"use strict";
import { useQuery } from "@tanstack/react-query";
import { usePublicClient } from "wagmi";
import { formatUnits } from "viem";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { MORPHO_ADDRESS, MORPHO_MARKETS, MORPHO_ABI, MORPHO_ORACLE_ABI } from "constants/morpho";
const ORACLE_PRECISION = 36n;
function calculateBorrowRate(utilization) {
  const utilizationPercent = Number(utilization) / 1e18;
  const baseBorrowRate = 0.02;
  const maxRate = 0.5;
  const optimalUtilization = 0.9;
  if (utilizationPercent <= optimalUtilization) {
    return baseBorrowRate + utilizationPercent / optimalUtilization * 0.08;
  } else {
    const excessUtilization = (utilizationPercent - optimalUtilization) / (1 - optimalUtilization);
    return baseBorrowRate + 0.08 + excessUtilization * (maxRate - baseBorrowRate - 0.08);
  }
}
function convertOraclePriceToCollateralUsd(oraclePrice, collateralDecimals, loanDecimals, loanIsUsdc) {
  if (oraclePrice === 0n) {
    return { collateralPriceUsd: 0, loanPriceUsd: loanIsUsdc ? 1 : 0 };
  }
  const exponent = 36 - collateralDecimals + loanDecimals;
  const collateralPerLoan = Number(formatUnits(oraclePrice, exponent));
  if (loanIsUsdc) {
    return { collateralPriceUsd: collateralPerLoan, loanPriceUsd: 1 };
  } else {
    const loanPriceUsd = collateralPerLoan > 0 ? 1 / collateralPerLoan : 0;
    return { collateralPriceUsd: 1, loanPriceUsd };
  }
}
async function fetchMarketData(marketConfig, publicClient) {
  if (!publicClient) return null;
  try {
    const marketData = await publicClient.readContract({
      address: MORPHO_ADDRESS,
      abi: MORPHO_ABI,
      functionName: "market",
      args: [marketConfig.id]
    });
    const [totalSupplyAssets, , totalBorrowAssets] = marketData;
    let oraclePrice = 0n;
    try {
      oraclePrice = await publicClient.readContract({
        address: marketConfig.oracle,
        abi: MORPHO_ORACLE_ABI,
        functionName: "price"
      });
    } catch (e) {
      console.warn(`Failed to fetch oracle price for ${marketConfig.name}:`, e);
    }
    const availableLiquidity = totalSupplyAssets > totalBorrowAssets ? totalSupplyAssets - totalBorrowAssets : 0n;
    const utilizationRate = totalSupplyAssets > 0n ? Number(totalBorrowAssets * 10000n / totalSupplyAssets) / 100 : 0;
    const utilization = totalSupplyAssets > 0n ? totalBorrowAssets * BigInt(1e18) / totalSupplyAssets : 0n;
    const borrowRate = calculateBorrowRate(utilization) * 100;
    const supplyRate = borrowRate * (utilizationRate / 100);
    const loanDecimals = marketConfig.loanToken.decimals;
    const collateralDecimals = marketConfig.collateralToken.decimals;
    const loanIsUsdc = marketConfig.loanToken.symbol.toUpperCase() === "USDC";
    const { collateralPriceUsd, loanPriceUsd } = convertOraclePriceToCollateralUsd(
      oraclePrice,
      collateralDecimals,
      loanDecimals,
      loanIsUsdc
    );
    const totalSupplyAmount = Number(formatUnits(BigInt(totalSupplyAssets), loanDecimals));
    const totalBorrowAmount = Number(formatUnits(BigInt(totalBorrowAssets), loanDecimals));
    const availableLiquidityAmount = Number(formatUnits(availableLiquidity, loanDecimals));
    return {
      id: marketConfig.id,
      name: marketConfig.name,
      description: marketConfig.description,
      collateralToken: marketConfig.collateralToken,
      loanToken: marketConfig.loanToken,
      oracle: marketConfig.oracle,
      lltv: marketConfig.lltv,
      lltvPercent: marketConfig.lltvPercent,
      totalSupplyAssets: BigInt(totalSupplyAssets),
      totalSupplyAssetsFormatted: formatUnits(BigInt(totalSupplyAssets), loanDecimals),
      totalSupplyUsd: totalSupplyAmount * loanPriceUsd,
      totalBorrowAssets: BigInt(totalBorrowAssets),
      totalBorrowAssetsFormatted: formatUnits(BigInt(totalBorrowAssets), loanDecimals),
      totalBorrowUsd: totalBorrowAmount * loanPriceUsd,
      availableLiquidity,
      availableLiquidityFormatted: formatUnits(availableLiquidity, loanDecimals),
      availableLiquidityUsd: availableLiquidityAmount * loanPriceUsd,
      utilizationRate,
      borrowRate,
      supplyRate,
      oraclePrice,
      collateralPriceUsd,
      loanPriceUsd,
      chainId: marketConfig.chainId
    };
  } catch (error) {
    console.error(`Failed to fetch market data for ${marketConfig.name}:`, error);
    return null;
  }
}
export function useMorphoMarkets(chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-markets", chainId],
    queryFn: async () => {
      if (!publicClient) return [];
      const marketConfigs = Object.values(MORPHO_MARKETS).filter((m) => m.chainId === chainId);
      const results = await Promise.all(marketConfigs.map((config) => fetchMarketData(config, publicClient)));
      return results.filter((m) => m !== null);
    },
    enabled: !!publicClient,
    refetchInterval: 3e4,
    staleTime: 15e3
  });
}
export function useMorphoMarket(marketId, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-market", marketId, chainId],
    queryFn: async () => {
      if (!publicClient || !marketId) return null;
      const marketConfig = Object.values(MORPHO_MARKETS).find(
        (m) => m.id.toLowerCase() === marketId.toLowerCase() && m.chainId === chainId
      );
      if (!marketConfig) {
        console.error(`Market config not found for ID ${marketId}`);
        return null;
      }
      return fetchMarketData(marketConfig, publicClient);
    },
    enabled: !!publicClient && !!marketId,
    refetchInterval: 3e4,
    staleTime: 15e3
  });
}
export function useMorphoMarketByTokens(collateralToken, loanToken, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-market-by-tokens", collateralToken, loanToken, chainId],
    queryFn: async () => {
      if (!publicClient || !collateralToken || !loanToken) return null;
      const marketConfig = Object.values(MORPHO_MARKETS).find(
        (m) => m.collateralToken.address.toLowerCase() === collateralToken.toLowerCase() && m.loanToken.address.toLowerCase() === loanToken.toLowerCase() && m.chainId === chainId
      );
      if (!marketConfig) {
        console.error(`Market config not found for tokens ${collateralToken} / ${loanToken}`);
        return null;
      }
      return fetchMarketData(marketConfig, publicClient);
    },
    enabled: !!publicClient && !!collateralToken && !!loanToken,
    refetchInterval: 3e4,
    staleTime: 15e3
  });
}
