"use strict";
import { useQuery } from "@tanstack/react-query";
import { usePublicClient } from "wagmi";
import { formatUnits } from "viem";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import {
  MORPHO_ADDRESS,
  MORPHO_MARKETS,
  MORPHO_ABI,
  MORPHO_ORACLE_ABI,
  ERC20_ABI
} from "constants/morpho";
function convertSharesToAssets(shares, totalShares, totalAssets) {
  if (totalShares === 0n) return 0n;
  return shares * totalAssets / totalShares;
}
async function fetchUserPositionForMarket(marketConfig, userAddress, publicClient) {
  if (!publicClient) return null;
  try {
    const [positionData, marketData] = await publicClient.multicall({
      allowFailure: false,
      contracts: [
        {
          address: MORPHO_ADDRESS,
          abi: MORPHO_ABI,
          functionName: "position",
          args: [marketConfig.id, userAddress]
        },
        {
          address: MORPHO_ADDRESS,
          abi: MORPHO_ABI,
          functionName: "market",
          args: [marketConfig.id]
        }
      ]
    });
    const [supplyShares, borrowShares, collateral] = positionData;
    const [totalSupplyAssets, totalSupplyShares, totalBorrowAssets, totalBorrowShares] = marketData;
    const supplyAssets = convertSharesToAssets(BigInt(supplyShares), BigInt(totalSupplyShares), BigInt(totalSupplyAssets));
    const borrowAssets = convertSharesToAssets(BigInt(borrowShares), BigInt(totalBorrowShares), BigInt(totalBorrowAssets));
    const [walletCollateralBalance, walletLoanBalance] = await publicClient.multicall({
      allowFailure: false,
      contracts: [
        {
          address: marketConfig.collateralToken.address,
          abi: ERC20_ABI,
          functionName: "balanceOf",
          args: [userAddress]
        },
        {
          address: marketConfig.loanToken.address,
          abi: ERC20_ABI,
          functionName: "balanceOf",
          args: [userAddress]
        }
      ]
    });
    let oraclePrice = BigInt(1e36);
    try {
      oraclePrice = await publicClient.readContract({
        address: marketConfig.oracle,
        abi: MORPHO_ORACLE_ABI,
        functionName: "price"
      });
    } catch (e) {
      console.warn(`Failed to fetch oracle price for ${marketConfig.name}:`, e);
    }
    const collateralDecimals = marketConfig.collateralToken.decimals;
    const loanDecimals = marketConfig.loanToken.decimals;
    const collateralValueInLoan = BigInt(collateral) * oraclePrice / BigInt(10 ** 36);
    const maxBorrow = collateralValueInLoan * marketConfig.lltv / BigInt(1e18);
    let healthFactor = Infinity;
    if (borrowAssets > 0n) {
      healthFactor = Number(maxBorrow * BigInt(1e18) / borrowAssets) / 1e18;
    }
    let ltv = 0;
    if (collateralValueInLoan > 0n) {
      ltv = Number(borrowAssets * BigInt(1e18) / collateralValueInLoan) / 1e16;
    }
    const collateralValueUsd = Number(formatUnits(BigInt(collateral), collateralDecimals));
    const borrowValueUsd = Number(formatUnits(borrowAssets, loanDecimals));
    return {
      marketId: marketConfig.id,
      marketName: marketConfig.name,
      collateralToken: marketConfig.collateralToken,
      loanToken: marketConfig.loanToken,
      supplyShares: BigInt(supplyShares),
      borrowShares: BigInt(borrowShares),
      collateral: BigInt(collateral),
      collateralFormatted: formatUnits(BigInt(collateral), collateralDecimals),
      borrowAssets,
      borrowAssetsFormatted: formatUnits(borrowAssets, loanDecimals),
      supplyAssets,
      supplyAssetsFormatted: formatUnits(supplyAssets, loanDecimals),
      healthFactor,
      ltv,
      lltvPercent: marketConfig.lltvPercent,
      collateralValueUsd,
      borrowValueUsd,
      walletCollateralBalance,
      walletCollateralBalanceFormatted: formatUnits(walletCollateralBalance, collateralDecimals),
      walletLoanBalance,
      walletLoanBalanceFormatted: formatUnits(walletLoanBalance, loanDecimals)
    };
  } catch (error) {
    console.error(`Failed to fetch user position for market ${marketConfig.name}:`, error);
    return null;
  }
}
export function useMorphoUserBorrowPosition(marketId, userAddress, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-user-borrow-position", marketId, userAddress, chainId],
    queryFn: async () => {
      if (!publicClient || !marketId || !userAddress) return null;
      const marketConfig = Object.values(MORPHO_MARKETS).find(
        (m) => m.id.toLowerCase() === marketId.toLowerCase() && m.chainId === chainId
      );
      if (!marketConfig) {
        console.error(`Market config not found for ID ${marketId}`);
        return null;
      }
      return fetchUserPositionForMarket(marketConfig, userAddress, publicClient);
    },
    enabled: !!publicClient && !!marketId && !!userAddress,
    refetchInterval: 15e3,
    staleTime: 1e4
  });
}
export function useMorphoUserAllBorrowPositions(userAddress, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-user-all-borrow-positions", userAddress, chainId],
    queryFn: async () => {
      if (!publicClient || !userAddress) return [];
      const marketConfigs = Object.values(MORPHO_MARKETS).filter((m) => m.chainId === chainId);
      const positions = await Promise.all(
        marketConfigs.map((config) => fetchUserPositionForMarket(config, userAddress, publicClient))
      );
      return positions.filter((p) => p !== null).filter((p) => p.collateral > 0n || p.borrowAssets > 0n || p.supplyAssets > 0n);
    },
    enabled: !!publicClient && !!userAddress,
    refetchInterval: 15e3,
    staleTime: 1e4
  });
}
export function calculateMaxBorrow(collateralAmount, oraclePrice, lltv, currentBorrow) {
  const collateralValueInLoan = collateralAmount * oraclePrice / BigInt(10 ** 36);
  const maxBorrowCapacity = collateralValueInLoan * lltv / BigInt(1e18);
  if (maxBorrowCapacity > currentBorrow) {
    return maxBorrowCapacity - currentBorrow;
  }
  return 0n;
}
export function calculateHealthFactorAfterBorrow(collateralAmount, oraclePrice, lltv, currentBorrow, additionalBorrow) {
  const collateralValueInLoan = collateralAmount * oraclePrice / BigInt(10 ** 36);
  const maxBorrow = collateralValueInLoan * lltv / BigInt(1e18);
  const newBorrow = currentBorrow + additionalBorrow;
  if (newBorrow === 0n) return Infinity;
  return Number(maxBorrow * BigInt(1e18) / newBorrow) / 1e18;
}
